// Static (Compile-time) Initialization (Default mutex type)
pthread_mutex_t mtx_static = PTHREAD_MUTEX_INITIALIZER;

// Dynamic (Run-time) Initialization

pthread_mutex_t mtx_dynamic;

// Initialize with NULL (default attributes)
int status = pthread_mutex_init(&mtx_dynamic, NULL);

// Using custom attributes for specific behavior (e.g., error checking)
pthread_mutexattr_t attr;
pthread_mutexattr_init(&attr);
pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_ERRORCHECK);

int status_2 = pthread_mutex_init(&mtx_dynamic, &attr);

pthread_mutexattr_destroy(&attr);
